import time, functools

def timer(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        t = time.perf_counter()
        result = func(*args, **kwargs)
        print(f"{func.__name__} 用时 {time.perf_counter() - t:.6f}s")
        return result
    return wrapper

@timer
def slow_sum(n):
    return sum(range(n))

r = slow_sum(1_000_000)
print("结果:", r)
print("函数名保留:", slow_sum.__name__)

