# 带参数的装饰器 + 缓存
from functools import lru_cache

def repeat(times):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            for _ in range(times):
                func(*args, **kwargs)
        return wrapper
    return decorator

def announce(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        print("开始执行", func.__name__)
        r = func(*args, **kwargs)
        print("结束执行")
        return r
    return wrapper

@announce
@repeat(2)
def greet(name):
    print(f"Hello {name}")

greet("Tom")

