# 懒加载描述符
class Lazy:
    def __init__(self, func):
        self.func = func
        self.name = func.__name__
    def __get__(self, obj, owner):
        if obj is None:
            return self
        value = self.func(obj)
        setattr(obj, self.name, value)  # 缓存
        return value

class Data:
    @Lazy
    def expensive(self):
        print("只计算一次...")
        return sum(range(100))

d = Data()
print(d.expensive)   # 计算
print(d.expensive)   # 用缓存，不再计算

