# 用元类在类定义时校验/改写
class EnforceNamespace(type):
    def __new__(mcs, name, bases, ns):
        # 要求类提供 name 属性
        if name != "Base" and "name" not in ns:
            raise TypeError(f"{name} 缺少 name 属性")
        return super().__new__(mcs, name, bases, ns)

class Base(metaclass=EnforceNamespace):
    pass

class Good(Base):
    name = "ok"

try:
    class Bad(Base):
        pass
except TypeError as e:
    print("被拦截:", e)

