# 自动给方法添加前缀（类似骨架）
class AutoPrefix(type):
    def __new__(mcs, name, bases, ns):
        for k in list(ns):
            if k.startswith("do_"):
                ns["api_" + k[3:]] = ns[k]
        return super().__new__(mcs, name, bases, ns)

class Service(metaclass=AutoPrefix):
    def do_save(self):
        return "saved"

s = Service()
print(s.do_save())          # saved
print(s.api_save())         # saved（自动生成的别名）

